			<!-- 摄影作品首页展示 -->
			<div class="homeList_view">
				<div class="homeList_title">
                    <span>摄影作品展示</span>
                </div>
				<div class="homeList">
					<div class="item" v-for="(item,index) in sheyingzuopinHomeList" :key="index" @click="detailClick('sheyingzuopin',item.id)">
						<div class="img-box">
							<img v-if="isHttp(item.zuopintupian)" :src="item.zuopintupian.split(',')[0]" alt="">
							<img v-else :src="item.zuopintupian?$config.url + item.zuopintupian.split(',')[0]:''" alt="">
						</div>
						<div class="content-box">
							<div class="title">
								{{item.zuopinmingcheng}}
							</div>
							<div class="title">
								{{item.sheyingzhanghao}}
							</div>
						</div>
					</div>
				</div>
				<div class="homeList_more_view" @click="moreClick('sheyingzuopin')">
					<span class="homeList_more_text">查看更多</span>
				</div>
			</div>
			<!--友情链接-->
			<div class="friendLink" v-if="friendLinkList && friendLinkList.length">
				<div class="title-wrapper">
					<div>友情链接</div>
				</div>
				<div class="list">
					<div class="item" v-for="(item,index) in friendLinkList" :key="index" @click="friendlinkClick(item.linkUrl)">
						<img class="img" :src="item.linkImage?($config.url + item.linkImage.split(',')[0]): ''">
						<div class="name">{{item.linkName}}</div>
					</div>
				</div>
			</div>
		</div>
	</div>
</template>

<script setup>
	import {
		ref,
		getCurrentInstance
	} from 'vue';
	import moment from 'moment'
	import {
		useRouter
	} from 'vue-router';
	const context = getCurrentInstance()?.appContext.config.globalProperties;
	const router = useRouter()
	//摄影作品首页展示
	const sheyingzuopinHomeList = ref([])
	const getsheyingzuopinHomeList = () => {
		let params = {
			page: 1,
			limit: 8,
            sort:'id',
            order:'desc',
		}
		context?.$http({
			url: 'sheyingzuopin/list',
			method: 'get',
			params: params
		}).then(res => {
			sheyingzuopinHomeList.value = res.data.data.list
			sheyingzuopinHomeList.value.forEach(item=>{
				if(!isHttp(item.zuopintupian)){
					item.imgUrls = item.zuopintupian.split(',').map(item=>context.$config.url+item)
				}
			})
		})
	}
	// 友情链
	const friendLinkList = ref([])
	const getFriendLinkList = ()=>{
		context.$http.get('friendshiplink/list', {
            params:{
                page: 1,
                limit: 10,
                sort:'id',
                order:'desc',
            }
        }).then(res => {
			if(res.data.code == 0) {
				friendLinkList.value = res.data.data.list
			}
		})
	}
	const friendlinkClick = (url)=>{
		if(url){
			window.open(url)
		}
	}
	//判断图片链接是否带http
	const isHttp = (str) => {
        return str && str.substr(0,4)=='http';
    }
	//跳转详情
	const detailClick = (table,id) => {
		router.push(`/index/${table}Detail?id=${id}`)
	}
	const moreClick = (table) => {
		router.push(`/index/${table}List`)
	}
	const init = () => {
		//摄影作品首页展示
		getsheyingzuopinHomeList()
		getFriendLinkList()
	}
	init()
</script>

