<template>
	<div class="edit_view" :style='{}'>
        <div class="breadcrumb-wrapper" style="width: 100%;">
            <div class="bread_view">
                <el-breadcrumb separator="" class="breadcrumb">
                    <el-breadcrumb-item class="first_breadcrumb" :to="{ path: '/' }">首页</el-breadcrumb-item>
                    <el-breadcrumb-item class="second_breadcrumb" v-for="(item,index) in breadList" :key="index">{{item.name}}</el-breadcrumb-item>
                </el-breadcrumb>
            </div>
        </div>
		<el-form ref="formRef" :model="form" class="add_form" label-width="120px" :rules="rules">
			<el-row>
				<el-col :span="12">
					<el-form-item label="摄影账号" prop="sheyingzhanghao">
						<el-select
							class="list_sel"
							:disabled="!isAdd||disabledForm.sheyingzhanghao?true:false"
							v-model="form.sheyingzhanghao"
							placeholder="请选择摄影账号"
							style="width:100%;"
							@change="sheyingzhanghaoChange">
							<el-option v-for="(item,index) in sheyingzhanghaoLists" :label="item" :value="item">
							</el-option>
						</el-select>
					</el-form-item>
				</el-col>
				<el-col :span="12">
					<el-form-item label="摄影姓名" prop="sheyingxingming">
						<el-input class="list_inp"
                                  v-model="form.sheyingxingming"
                                  placeholder="摄影姓名"
                                  type="text"
							      :readonly="!isAdd||disabledForm.sheyingxingming?true:false" />
					</el-form-item>
				</el-col>

				<el-col :span="12">
					<el-form-item label="预约价格" prop="yuyuejiage">
						<el-input class="list_inp"
                                  v-model.number="form.yuyuejiage"
                                  placeholder="预约价格"
                                  type="number"
							      :readonly="!isAdd||disabledForm.yuyuejiage?true:false" />
					</el-form-item>
				</el-col>

				<el-col :span="12">
					<el-form-item label="用户账号" prop="yonghuzhanghao">
						<el-input class="list_inp"
                                  v-model="form.yonghuzhanghao"
                                  placeholder="用户账号"
                                  type="text"
							      :readonly="!isAdd||disabledForm.yonghuzhanghao?true:false" />
					</el-form-item>
				</el-col>

				<el-col :span="12">
					<el-form-item label="用户姓名" prop="yonghuxingming">
						<el-input class="list_inp"
                                  v-model="form.yonghuxingming"
                                  placeholder="用户姓名"
                                  type="text"
							      :readonly="!isAdd||disabledForm.yonghuxingming?true:false" />
					</el-form-item>
				</el-col>

				<el-col :span="12">
					<el-form-item label="预约摄影日期" prop="yuyuesheyingriqi">
						<el-date-picker
							class="list_date"
							v-model="form.yuyuesheyingriqi"
							format="YYYY-MM-DD"
							value-format="YYYY-MM-DD"
							type="date"
							style="width:100%;"
							:readonly="!isAdd||disabledForm.yuyuesheyingriqi?true:false"
							placeholder="请选择预约摄影日期"
							@change="selecteSheyingshiyuyue()">
						</el-date-picker>
					</el-form-item>
				</el-col>
				<el-col :span="12">
					<el-form-item label="选择时间段" prop="yuyueshijianduan">
						<el-select
								class="list_sel"
								v-model="form.yuyueshijianduan"
								placeholder="请选择预约摄影时间段"
								style="width:100%;"
								:disabled="!form.yuyuesheyingriqi"
						>
							<el-option
									v-for="option in timeOptions"
									:key="option.value"
									:label="option.label"
									:value="option.value"
									:disabled="isOptionDisabled(option.value)"
							></el-option>
						</el-select>
					</el-form-item>
				</el-col>

			</el-row>
			<div class="formModel_btn_box">
				<el-button class="formModel_cancel" @click="backClick">取消</el-button>
				<el-button class="formModel_confirm"
                           @click="save"
                           type="success"
				>
					保存
				</el-button>
			</div>
		</el-form>
	</div>
</template>
<script setup>
	import {
		ref,
		getCurrentInstance,
		watch,
		onUnmounted,
		onMounted,
		nextTick,
		computed
	} from 'vue';
	import {
		useRoute,
		useRouter
	} from 'vue-router';
    import moment from "moment";
	const context = getCurrentInstance()?.appContext.config.globalProperties;
	const route = useRoute()
	const router = useRouter()
	//基础信息
	const tableName = 'sheyingshiyuyue'
	const formName = '摄影师预约'
	//基础信息
	const breadList = ref([{
		name: formName
	}])
	//获取唯一标识
	const getUUID =()=> {
      return new Date().getTime();
    }
	//form表单
	const form = ref({
		sheyingzhanghao: '',
		sheyingxingming: '',
		yuyuejiage: 0,
		sfsh: '',
		shhf: '',
		yonghuzhanghao: '',
		yonghuxingming: '',
		yuyuesheyingriqi: '',
		yuyueshijianduan:'',
		crossuserid: '',
		crossrefid: '',
	})
	const formRef = ref(null)
	const id = ref(0)
	const type = ref('')
	const disabledForm = ref({
		sheyingzhanghao : false,
		sheyingxingming : false,
		yuyuejiage : false,
		sfsh : false,
		shhf : false,
		yonghuzhanghao : false,
		yonghuxingming : false,
		yuyuesheyingriqi : false,
		ispay : false,
		crossuserid : false,
		crossrefid : false,
	})
	const isAdd = ref(false)
	//表单验证
	const rules = ref({
		sheyingzhanghao: [
		],
		sheyingxingming: [
		],
		yuyuejiage: [
			{ validator: context.$toolUtil.validator.number, trigger: 'blur' },
		],
		sfsh: [
		],
		shhf: [
		],
		yonghuzhanghao: [
		],
		yonghuxingming: [
		],
		yuyuesheyingriqi: [
			{required: true,message: '请选择预约摄影日期',trigger: 'blur'}
		],
		yuyueshijianduan: [
			{required: true,message: '请选择预约时间段',trigger: 'change'}
		],
		ispay: [
		],
		crossuserid: [
		],
		crossrefid: [
		],
	})
	//摄影账号列表
	const sheyingzhanghaoLists = ref([])
	//methods

	//methods
	//获取info
	const getInfo = ()=>{
		context?.$http({
			url: `${tableName}/info/${id.value}`,
			method: 'get'
		}).then(res => {
			let reg=new RegExp('../../../file','g')
			form.value = res.data.data
		})
	}
	const crossRow = ref('')
	const crossTable = ref('')
	const crossTips = ref('')
	const crossColumnName = ref('')
	const crossColumnValue = ref('')
	//初始化
	const init = (formId=null,formType='add',formNames='',row=null,table=null,statusColumnName=null,tips=null,statusColumnValue=null) => {
		if(formId){
			id.value = formId
			type.value = formType
		}
		if(formType == 'add'){
			isAdd.value = true
		}else if(formType == 'info'){
			isAdd.value = false
			getInfo()
		}else if(formType == 'edit'){
			isAdd.value = true
			getInfo()
		}
		else if(formType == 'cross'){
			isAdd.value = true
			// getInfo()
			for(let x in row){
				if(x=='sheyingzhanghao'){
					form.value.sheyingzhanghao = row[x];
					disabledForm.value.sheyingzhanghao = true;
					continue;
				}
				if(x=='sheyingxingming'){
					form.value.sheyingxingming = row[x];
					disabledForm.value.sheyingxingming = true;
					continue;
				}
				if(x=='yuyuejiage'){
					form.value.yuyuejiage = row[x];
					disabledForm.value.yuyuejiage = true;
					continue;
				}
				if(x=='yonghuzhanghao'){
					form.value.yonghuzhanghao = row[x];
					disabledForm.value.yonghuzhanghao = true;
					continue;
				}
				if(x=='yonghuxingming'){
					form.value.yonghuxingming = row[x];
					disabledForm.value.yonghuxingming = true;
					continue;
				}
				if(x=='yuyuesheyingriqi'){
					form.value.yuyuesheyingriqi = row[x];
					disabledForm.value.yuyuesheyingriqi = true;
					continue;
				}
				if(x=='crossuserid'){
					form.value.crossuserid = row[x];
					disabledForm.value.crossuserid = true;
					continue;
				}
				if(x=='crossrefid'){
					form.value.crossrefid = row[x];
					disabledForm.value.crossrefid = true;
					continue;
				}
			}
			if(row){
				crossRow.value = row
			}
			if(table){
				crossTable.value = table
			}
			if(tips){
				crossTips.value = tips
			}
			if(statusColumnName){
				crossColumnName.value = statusColumnName
			}
			if(statusColumnValue){
				crossColumnValue.value = statusColumnValue
			}
		}
		context?.$http({
			url: `${context?.$toolUtil.storageGet('frontSessionTable')}/session`,
			method: 'get'
		}).then(res => {
			var json = res.data.data
			if(json.hasOwnProperty('yonghuzhanghao') && context?.$toolUtil.storageGet("frontRole")!="管理员"){
				form.value.yonghuzhanghao = json.yonghuzhanghao
				disabledForm.value.yonghuzhanghao = true;
			}
			if(json.hasOwnProperty('yonghuxingming') && context?.$toolUtil.storageGet("frontRole")!="管理员"){
				form.value.yonghuxingming = json.yonghuxingming
				disabledForm.value.yonghuxingming = true;
			}
            if (localStorage.getItem('autoSave')) {
                localStorage.removeItem('autoSave')
                save()
            }
		})
		context?.$http({
			url: `option/sheyingshi/sheyingzhanghao`,
			method: 'get'
		}).then(res=>{
			sheyingzhanghaoLists.value = res.data.data
		})
		//由上级字段带出不可改
		disabledForm.value.sheyingxingming = true;
	}
	//初始化
	//取消
	const backClick = () => {
		history.back()
	}
	//摄影账号回调
	const sheyingzhanghaoChange=()=>{
		context?.$http({
			url: `follow/sheyingshi/sheyingzhanghao?columnValue=` + form.value.sheyingzhanghao,
			method: 'get'
		}).then(res=>{
			//带出摄影姓名字段
			if(res.data.data.sheyingxingming){
				form.value.sheyingxingming = res.data.data.sheyingxingming
			}
		})
	}
	//提交
	const save=()=>{
		var table = crossTable.value
		var objcross = JSON.parse(JSON.stringify(crossRow.value))
		let crossUserId = ''
		let crossRefId = ''
		let crossOptNum = ''
		if(type.value == 'cross'){
			if(crossColumnName.value!=''){
				if(!crossColumnName.value.startsWith('[')){
					for(let o in objcross){
						if(o == crossColumnName.value){
							objcross[o] = crossColumnValue.value
						}
					}
					//修改跨表数据
					changeCrossData(objcross)
				}else{
					crossUserId = context?.$toolUtil.storageGet('userid')
					crossRefId = objcross['id']
					crossOptNum = crossColumnName.value.replace(/\[/,"").replace(/\]/,"")
				}
			}
		}
		formRef.value.validate((valid)=>{
			if(valid){
				if(crossUserId&&crossRefId){
					form.value.crossuserid = crossUserId
					form.value.crossrefid = crossRefId
					let params = {
						page: 1,
						limit: 1000,
						crossuserid:form.value.crossuserid,
						crossrefid:form.value.crossrefid,
					}
					context?.$http({
						url: `${tableName}/page`,
						method: 'get',
						params: params
					}).then(res=>{
						if(res.data.data.total>=crossOptNum){
							context?.$toolUtil.message(`${crossTips.value}`,'error')
							return false
						}else{
							context?.$http({
								url: `${tableName}/${!form.value.id ? "save" : "update"}`,
								method: 'post',
								data: form.value
							}).then(res=>{
                                context?.$toolUtil.message(`操作成功`,'success')
                                history.back()
							})
						}
					})
				}else{
					context?.$http({
						url: `${tableName}/${!form.value.id ? "save" : "update"}`,
						method: 'post',
						data: form.value
					}).then(res=>{
                        context?.$toolUtil.message(`操作成功`,'success')
                        history.back()
					})
				}
			}
		})
	}
	//修改跨表数据
	const changeCrossData=(row)=>{
		if(type.value == 'cross'){
			context?.$http({
				url: `${crossTable.value}/update`,
				method: 'post',
				data: row
			}).then(res=>{})
		}
	}

	// 时间段选项
	const timeOptions = [
		{ label: "08:00-09:00", value: "08:00-09:00" },
		{ label: "09:00-10:00", value: "09:00-10:00" },
		{ label: "10:00-11:00", value: "10:00-11:00" },
		{ label: "11:00-12:00", value: "11:00-12:00" },
		{ label: "13:00-14:00", value: "13:00-14:00" },
		{ label: "14:00-15:00", value: "14:00-15:00" },
		{ label: "15:00-16:00", value: "15:00-16:00" },
		{ label: "16:00-17:00", value: "16:00-17:00" }
	];

	// 判断选项是否禁用
	const isOptionDisabled = (optionValue) => {
		console.log(sheyingshiyuyueList.value,"111111")
		if (!sheyingshiyuyueList.value) return false;
		return sheyingshiyuyueList.value.some(item => item.yuyueshijianduan === optionValue);
	};

	//日期查询摄影师预约集合
	const sheyingshiyuyueList = ref([])
	//根据日期查询摄影师的预约情况
	const selecteSheyingshiyuyue=()=>{
		    let params={
				sheyingzhanghao:form.value.sheyingzhanghao,
				yuyuesheyingriqi:form.value.yuyuesheyingriqi
			}
			context?.$http({
				url: `${tableName}/list`,
				method: 'get',
				params:params
			}).then(res=>{
				console.log(res.data.data.list,"data")
				sheyingshiyuyueList.value = res.data.data.list
			})

	}
	//获取当前系统时间
	const getFormattedDate=()=> {
		const now = new Date();
		const year = now.getFullYear();
		const month = (now.getMonth() + 1).toString().padStart(2, '0');
		const day = now.getDate().toString().padStart(2, '0');
		return `${year}-${month}-${day}`;
	}
	onMounted(()=>{
		type.value = route.query.type?route.query.type:'add'
		let row = null
		let table = null
		let statusColumnName = null
		let tips = null
		let statusColumnValue = null
		if(type.value == 'cross'){
			row = context?.$toolUtil.storageGet('crossObj')?JSON.parse(context?.$toolUtil.storageGet('crossObj')):{}
			table = context?.$toolUtil.storageGet('crossTable')
			statusColumnName = context?.$toolUtil.storageGet('crossStatusColumnName')
			tips = context?.$toolUtil.storageGet('crossTips')
			statusColumnValue = context?.$toolUtil.storageGet('crossStatusColumnValue')
		}
		init(route.query.id?route.query.id:null, type.value,'', row, table, statusColumnName, tips, statusColumnValue)
	})
    onUnmounted(()=>{
        Object.keys(localStorage).map(item=>{
            if(item.startsWith('cross')){
                localStorage.removeItem(item)
            }
        })
    })
</script>
<style lang="scss" scoped>
	// 面包屑盒子
	.bread_view {
		:deep(.breadcrumb) {
			.el-breadcrumb__separator {
			}
			.first_breadcrumb {
				.el-breadcrumb__inner {
				}
			}
			.second_breadcrumb {
				.el-breadcrumb__inner {
				}
			}
		}
	}
	// 表单
	.add_form{
		// form item
		:deep(.el-form-item) {
			//label
			.el-form-item__label {
			}
			// 内容盒子
			.el-form-item__content {
				// 输入框
				.list_inp {

				}
				//日期选择器
				.list_date {
				}
				// 下拉框
				.list_sel {
					//去掉默认样式
					.select-trigger{
						height: 100%;
						.el-input{
							height: 100%;
						}
					}
				}
			}
		}
	}
	// 按钮盒子
	.formModel_btn_box {
		.formModel_cancel {
		}
		.formModel_cancel:hover {
		}

		.formModel_confirm {
		}
		.formModel_confirm:hover {
		}
	}
</style>
